INSERT INTO public.cro_evidence (topic, principle, context, limitations, recommended_application, metric, applies_to, not_applicable_to, audience, devices, funnel_type, tags, source_name, source_url, evidence_level, active) VALUES ('Visuele hiërarchie en scanpatronen', 'Bezoekers scannen landingspagina''s in een F- of Z-patroon en geven de meeste aandacht aan de eerste zichtbare content; visuele hiërarchie (grootte, contrast, positie) stuurt waar de blik heen gaat.', 'Nielsen Norman Group eyetracking-onderzoek naar lees- en scanpatronen op webpagina''s.', 'Patronen zijn gemiddelden over veel sites; geen garantie voor een specifieke pagina. Niet getest op ZoetBezorgen-verkeer.', 'Plaats propositie, belangrijkste bewijs en primaire CTA in de eerste viewport en geef ze de grootste visuele gewichten op de pagina.', 'cta_rate', ARRAY['hero','headline','page_structure']::text[], ARRAY[]::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['design','visual hierarchy','above the fold']::text[], 'Nielsen Norman Group — Scanning Patterns', 'https://www.nngroup.com/articles/text-scanning-patterns-eyetracking/', 'MODERATE', true), ('Hero-compositie en eerste indruk', 'Een hero met één dominant, relevant beeld en één duidelijke boodschap presteert beter dan een hero met meerdere concurrerende elementen; visuele complexiteit verlaagt de waargenomen aantrekkelijkheid binnen de eerste 50ms.', 'Google Research (Reinecke et al.) over eerste-indruk-vorming en visuele complexiteit van websites.', 'Laboratoriumonderzoek met korte blootstelling; vertaalt eerste indruk, geen gemeten conversie. Effectgrootte per branche onbekend.', 'Ontwerp de hero met één hoofdbeeld, één headline en één CTA; vermijd concurrerende badges, sliders en meerdere knoppen boven de fold.', 'cta_rate', ARRAY['hero','visual_treatment']::text[], ARRAY[]::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['design','hero','visual complexity']::text[], 'Google Research — Visual complexity and first impression of websites', 'https://research.google/pubs/the-role-of-visual-complexity-and-prototypicality-regarding-first-impression-of-websites/', 'MODERATE', true), ('Whitespace en leesbaarheid', 'Ruimte (whitespace) rond content verhoogt leesbaarheid en waargenomen kwaliteit; dicht opeengepakte layouts verhogen cognitieve belasting en verlagen begrip.', 'Klassiek usability-onderzoek (o.a. NN/g richtlijnen) naar whitespace en leesbaarheid.', 'Voornamelijk lees-/begripstudies, geen directe conversiemetingen. Te veel whitespace kan op mobiel juist scrollfrictie geven.', 'Geef elke sectie ademruimte, beperk het aantal elementen per scherm en gebruik dichtheid bewust als ritme-instrument (druk vs. rust).', 'engagement', ARRAY['page_structure','visual_treatment']::text[], ARRAY[]::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['design','whitespace','readability']::text[], 'Nielsen Norman Group — Whitespace in design', 'https://www.nngroup.com/articles/whitespace/', 'WEAK', true), ('Productbeeld-formaat en begeerte', 'Grote, gedetailleerde productafbeeldingen verhogen de waargenomen productkwaliteit en aankoopintentie; kleine of generieke thumbnails doen het product tekort.', 'Baymard Institute productpagina-onderzoek naar productbeeld-formaat en -kwaliteit in ecommerce.', 'Ecommerce-context; voor B2B-geschenken geldt het mechanisme (begeerte door beeld) naar verwachting ook, maar ongemeten.', 'Toon producten groot en appetijtelijk met minimaal één dominante showcase; vermijd uniforme kleine thumbnails als enige productpresentatie.', 'conversion_rate', ARRAY['products','visual_treatment']::text[], ARRAY[]::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['design','product imagery','showcase']::text[], 'Baymard Institute — Product image size and quality', 'https://baymard.com/blog/product-image-size', 'MODERATE', true), ('Mobiele visuele hiërarchie', 'Op mobiel bepaalt de eerste viewport disproportioneel of bezoekers verder scrollen; belangrijke content die alleen op desktop zichtbaar is, wordt op mobiel gemist.', 'NN/g mobiele usability-richtlijnen en Google/SOASTA mobiel onderzoek.', 'Gemiddelden over mobiele sites; exacte scrollpercentages verschillen per doelgroep en verkeersbron.', 'Zet op mobiel altijd propositie, hero-beeld en CTA als eerste drie elementen; test elke sectie expliciet op mobiele volgorde en beeldpositie.', 'bounce_rate', ARRAY['mobile','hero','page_structure']::text[], ARRAY[]::text[], 'both', 'mobile', ARRAY['lead_gen','quote_request']::text[], ARRAY['design','mobile','visual hierarchy']::text[], 'Nielsen Norman Group — Mobile usability', 'https://www.nngroup.com/topic/mobile/', 'MODERATE', true), ('CTA-contrast en -herhaling', 'Visueel contrasterende, ruim geplaatste CTA-knoppen worden vaker aangeklikt dan knoppen die visueel wegvallen; herhaling van de CTA na bewijsblokken verhoogt de totale kans op actie.', 'Samengevatte CRO-praktijk en case-studies (o.a. CXL, Unbounce) over CTA-contrast en -plaatsing.', 'Case-study-niveau, geen meta-analyse; effect sterk afhankelijk van context en bestaand ontwerp.', 'Geef de primaire CTA consequent het sterkste kleurcontrast op de pagina en herhaal hem na elke bewijsblok; houd secundaire acties visueel ondergeschikt.', 'cta_rate', ARRAY['cta','visual_treatment']::text[], ARRAY[]::text[], 'both', 'both', ARRAY['lead_gen','quote_request']::text[], ARRAY['design','cta','contrast']::text[], 'CXL — Call-to-action buttons: guidelines and best practices', 'https://cxl.com/blog/call-to-action-buttons/', 'WEAK', true);